clc;
clear;
close all;

readings = [ ...
    42 41 43 40 44 42 45 43 41 44 ...   %  1-10   calm
    46 45 47 44 48 46 49 47 45 48 ...   % 11-20   calm
    50 52 49 51 53 50 54 52 51 55 ...   % 21-30   warming
    58 56 60 57 59 62 61 58 60 63 ...   % 31-40   rising
    66 64 68 65 67 70 69 66 68 71 ...   % 41-50   crossing 70 (71 = first high)
    74 72 76 73 75 78 77 74 76 79 ...   % 51-60   sustained high  (10 highs)
    82 80 84 81 83 86 85 82 84 87 ...   % 61-70   sustained high  (20 highs)
    88 86 89 87 88 85 86 88 87 89 ...   % 71-80   peak            (30 highs -> ALERT at #80)
    84 82 85 83 81 84 82 80 83 81 ...   % 81-90   sustained high  (40 highs total)
    78 75 72 70 68 65 62 58 55 50 ...   % 91-100  falling back
    ];

threshold = 70;

[~, alertIdx] = stressMonitor(readings, threshold);
time = (1:numel(readings)) * 10 / 60;

figure("Color", "k"); %[output:25255009]
theme(gcf, "dark"); %[output:25255009]

plot(time, readings, "-b", "LineWidth", 1.5); hold on %[output:25255009]
yline(threshold, "--r"); %[output:25255009]

plot(time(alertIdx), readings(alertIdx), "ro", "MarkerFaceColor", "r"); %[output:25255009]

xlabel("Time(minutes)"); %[output:25255009]
ylabel("Stress(%)"); %[output:25255009]

title("Poultry Stress Readings"); %[output:25255009]
xlim([0 max(time)]); %[output:25255009]
ylim([0, 100]); %[output:25255009]

legend("Stress", "Threshold", "Alert"); %[output:25255009]
hold off %[output:25255009]

